static void testSSCommandsAndModes(void)
{
    xcronzone* Z=NULL;xtime At[2];xdatetime Local;ssFoldFixture(&Z,At,&Local);ssfixture F=ssFixture(At[1],&Local,2);xexecutor* E=ssPool(2,8);xcronselectedserviceconfig C=ssConfig(E,&F);C.Service.CommandLimit=2;xrtAtomic32Store(&F.HoldClock,1,XMEMORY_RELEASE);ssStart(&F,&C);ssUntil(&F.ClockHeld,1,"selected owner held at callback boundary");xcronjobconfig J=ssJob(Z,&F,At[0],At[1]);xcronrequestid A,B,Sentinel=77;
    xcronserviceissue I={XCRON_SERVICE_STALE,XERR_IO},OriginalI=I;xcronselectedreply R,Before;memset(&R,0x5a,sizeof(R));Before=R;
    testRequire(!xcronServiceAddAsync(F.Service,&J,&Sentinel,&I) && Sentinel==77 && !memcmp(&I,&OriginalI,sizeof(I)),"actual Add cannot change selected admission semantics");xrtClearError();
    testRequire(!xcronServiceAddSelectedAsync(F.Service,&J,(xcrondeliverypolicy){(xcronfoldpolicy)4,0},&Sentinel,&I) && Sentinel==77 && !memcmp(&I,&OriginalI,sizeof(I)),"invalid selected policy preserves request and Issue");xrtClearError();
    testRequire(xcronServiceAddSelectedAsync(F.Service,&J,(xcrondeliverypolicy){0,1},&A,NULL) && xcronServiceAddSelectedAsync(F.Service,&J,(xcrondeliverypolicy){2,1},&B,NULL),"selected queue snapshots independent policies/configs");xcronZoneRelease(Z);memset(&J,0xa5,sizeof(J));
    testRequire(!xcronServiceReapAsync(F.Service,&Sentinel,&I) && I.Code==XCRON_SERVICE_LIMIT && Sentinel==77,"selected command tickets reserve output until collection");xrtClearError();
    testRequire(xcronServiceCollectSelected(F.Service,A,1,&R,NULL)==XWAIT_TIMEOUT && !memcmp(&R,&Before,sizeof(R)),"selected timeout preserves accepted Data duty and output");
    xcronreply PlainReply;memset(&I,0x5a,sizeof(I));OriginalI=I;testRequire(xcronServiceCollect(F.Service,A,0,&PlainReply,&I)==XWAIT_ERROR && !memcmp(&I,&OriginalI,sizeof(I)),"actual Collect cannot truncate selected reply");xrtClearError();
    xcronservicecompletion PlainDone;size_t Count=99;xcronservicestats PlainStats;testRequire(!xcronServiceDrain(F.Service,&PlainDone,1,&Count,&I) && Count==99 && !xcronServiceInspect(F.Service,&PlainStats,&I) && !memcmp(&I,&OriginalI,sizeof(I)),"actual metadata/stats APIs reject selected mode atomically");xrtClearError();
    testRequire(!xcronServiceDrainSelected(F.Service,(xcronselectedservicecompletion*)F.Service,1,&Count,&I) && Count==99 && !xcronServiceDrainSelected(F.Service,(xcronselectedservicecompletion*)&R,SIZE_MAX,&Count,&I) && Count==99,"selected owned output and overflow spans rejected");xrtClearError();
    testRequire(xcronServiceClose(F.Service,false,NULL),"close before queued selected Add commit");xrtAtomic32Store(&F.HoldClock,0,XMEMORY_RELEASE);testRequire(xcronServiceWaitFor(F.Service,10000,NULL)==XWAIT_OK,"selected queued commands stopped");
    R=ssReply(F.Service,A);testRequire(R.Code==XCRON_SERVICE_CLOSED && R.Data==&F && !R.Job && R.Error,"first selected failed Add returns original Data");xrtErrorFree(R.Error);R=ssReply(F.Service,B);testRequire(R.Code==XCRON_SERVICE_CLOSED && R.Data==&F && !R.Job && R.Error,"second selected failed Add returns original Data");xrtErrorFree(R.Error);
    testRequire(xcronServiceCollectSelected(F.Service,A,0,&R,&I)==XWAIT_ERROR && I.Code==XCRON_SERVICE_STALE,"selected generation ticket collected exactly once");xrtClearError();ssClear(&F);
    F=ssFixture(At[1],&Local,2);C=ssConfig(E,&F);testRequire(xcronServiceCreate(&C.Service,&F.Service,NULL),"actual-only instance in extended service build");ssUntil(&F.ClockEntered,1,"actual extended owner ready");
    xcronselectedservicestats SelectedStats;testRequire(!xcronServiceInspectSelected(F.Service,&SelectedStats,&I) && xcronServiceCollectSelected(F.Service,1,0,&R,&I)==XWAIT_ERROR && !xcronServiceDrainSelected(F.Service,(xcronselectedservicecompletion*)&R,1,&Count,&I),"selected output APIs reject actual mode");xrtClearError();
    testRequire(xcronServiceClose(F.Service,false,NULL) && xcronServiceWaitFor(F.Service,10000,NULL)==XWAIT_OK && xcronServiceDestroy(F.Service,NULL),"ordinary mode remains usable");ssPoolEnd(E);
}
typedef struct sshostprobe {ssfixture* Fixture;xcronrequestid Request;xatomic32 Done;} sshostprobe;
static void ssHostProbe(ptr Raw)
{
    sshostprobe* P=Raw;xcronserviceissue I;xcronselectedreply R;testRequire(xcronServiceReapAsync(P->Fixture->Service,&P->Request,NULL),"unrelated host callback queues selected command");
    testRequire(xcronServiceCollectSelected(P->Fixture->Service,P->Request,10,&R,&I)==XWAIT_ERROR && I.Code==XCRON_SERVICE_THREAD,"unrelated borrowed-pool callback cannot block selected service");xrtClearError();
    testRequire(xcronServiceCollectSelected(P->Fixture->Service,P->Request,0,&R,NULL)==XWAIT_TIMEOUT,"unrelated callback can poll selected ticket");testRequire(xcronServiceWaitFor(P->Fixture->Service,10,&I)==XWAIT_ERROR && I.Code==XCRON_SERVICE_THREAD,"unrelated callback cannot join owner");xrtClearError();xrtAtomic32Store(&P->Done,1,XMEMORY_RELEASE);
}
static void testSSSelfWaitAndClock(void)
{
    xcronzone* Z=NULL;xtime At[2];xdatetime Local;ssFoldFixture(&Z,At,&Local);xcronZoneRelease(Z);ssfixture F=ssFixture(At[1],&Local,2);xexecutor* E=ssPool(1,8);xcronselectedserviceconfig C=ssConfig(E,&F);ssStart(&F,&C);xrtAtomic32Store(&F.Probes,1,XMEMORY_RELEASE);xcronServiceWake(F.Service,NULL);ssUntil(&F.ProbeDone,1,"selected owner probes completed");xcronselectedreply R=ssReply(F.Service,F.ProbeRequest);testRequire(R.Code==XCRON_SERVICE_OK && !R.Found && !R.Error,"owner probe ticket remains collectible");
    xrtAtomic32Store(&F.HoldClock,1,XMEMORY_RELEASE);xcronServiceWake(F.Service,NULL);ssUntil(&F.ClockHeld,1,"owner held for unrelated pool probe");sshostprobe P={.Fixture=&F};testRequire(xrtExecutorSubmit(E,ssHostProbe,&P,NULL,NULL),"run unrelated host callback");ssUntil(&P.Done,1,"unrelated callback probes completed");xrtAtomic32Store(&F.HoldClock,0,XMEMORY_RELEASE);R=ssReply(F.Service,P.Request);testRequire(R.Code==XCRON_SERVICE_OK && !R.Found && !R.Error,"unrelated callback timeout preserved ticket");
    xrtAtomic64Store(&F.Mono,99,XMEMORY_RELEASE);xcronServiceWake(F.Service,NULL);testRequire(xcronServiceWaitFor(F.Service,10000,NULL)==XWAIT_OK,"selected monotonic regression controlled shutdown");xcronselectedservicestats T=ssStats(F.Service);testRequire(T.Service.State==XCRON_SERVICE_FAILED && T.Service.Failure.Code==XCRON_SERVICE_CLOCK && !T.Service.ActiveNativeTimers,"typed selected clock failure and waiter release");xerror* Error=NULL;testRequire(xcronServiceFailure(F.Service,&Error,NULL),"owned selected sticky failure");xrtErrorFree(Error);ssClear(&F);ssPoolEnd(E);
    F=ssFixture(At[1],&Local,2);E=ssPool(1,8);C=ssConfig(E,&F);ssStart(&F,&C);xrtAtomic32Store(&F.FailClock,1,XMEMORY_RELEASE);xcronServiceWake(F.Service,NULL);testRequire(xcronServiceWaitFor(F.Service,10000,NULL)==XWAIT_OK && ssStats(F.Service).Service.Failure.Code==XCRON_SERVICE_CLOCK,"selected explicit clock read failure stops owner");ssClear(&F);ssPoolEnd(E);
}
static xcronrunresult ssUTCProc(const xcronrun* R,const xcronexecution* T,ptr Raw)
{
    ssfixture* F=Raw;const xcronexecutionlabel* L=xcronExecutionSelected(T);xdatetime Expected;xrtTimeSplit(R->ScheduledAt,&Expected);Expected.Offset=0;Expected.IsDST=-1;
    testRequire(R->Data==F && L && L->Candidates==1 && !memcmp(&L->Local,&Expected,sizeof(Expected)),"UTC service callback reads complete immutable label");xrtAtomic64FetchAdd(&F->Calls,1,XMEMORY_RELAXED);return XCRON_RUN_SUCCEEDED;
}
static void testSSBudgetsAndWarm(void)
{
    xdatetime Local;xrtTimeSplit(XRT_TIME_UNIX_EPOCH,&Local);Local.Offset=0;Local.IsDST=-1;ssfixture F=ssFixture(XRT_TIME_UNIX_EPOCH,&Local,1);xexecutor* E=ssPool(2,8);xcronselectedserviceconfig C=ssConfig(E,&F);xallocationbudget* Budget=NULL;testRequire(xrtAllocationBudgetCreate(SIZE_MAX,&Budget),"selected startup budget accounting");C.Service.InitializationBudget=Budget;xrtAtomic32Store(&F.HoldClock,1,XMEMORY_RELEASE);ssStart(&F,&C);ssUntil(&F.ClockHeld,1,"selected allocation snapshot before first clock returns");xcronselectedservicestats T=ssStats(F.Service);xallocationbudgetinfo BI={.Size=sizeof(BI)};testRequire(xrtAllocationBudgetInfo(Budget,&BI) && BI.LiveBytes>T.Service.Bytes && T.Service.Bytes==T.Service.ArenaBytes+T.Service.KernelBytes+T.Service.AdapterBytes,"selected byte snapshot matches retained components plus explicit thread charge");
    size_t Total=BI.LiveBytes,Arena=T.Service.ArenaBytes,Kernel=T.Service.KernelBytes,Adapter=T.Service.AdapterBytes,Thread=Total-Arena-Kernel-Adapter;xrtAtomic32Store(&F.HoldClock,0,XMEMORY_RELEASE);ssStop(&F);T=ssStats(F.Service);testRequire(!T.Service.AdapterBytes && !T.Service.Executor.Bytes && T.Service.Bytes==Arena+Kernel,"selected adapter bytes physically released before stop");ssClear(&F);testRequire(xrtAllocationBudgetInfo(Budget,&BI) && !BI.LiveBytes && !BI.LiveCount,"selected startup charges returned after physical cleanup");xrtAllocationBudgetFree(Budget);
    size_t Limits[]={1,Arena-1,Arena,Arena+Thread-1,Arena+Thread,Arena+Thread+Kernel-1,Arena+Thread+Kernel,Total-1,Total};
    for(size_t N=0;N<sizeof(Limits)/sizeof(*Limits);++N){F=ssFixture(XRT_TIME_UNIX_EPOCH,&Local,1);C=ssConfig(E,&F);testRequire(xrtAllocationBudgetCreate(Limits[N],&Budget),"selected allocation prefix quota");C.Service.InitializationBudget=Budget;xcronservice* Out=(xcronservice*)(uintptr_t)1;xcronserviceissue I;bool OK=xcronServiceCreateSelected(&C,&Out,&I);
        if(OK){F.Service=Out;ssStop(&F);ssClear(&F);}else {testRequire(Out==(xcronservice*)(uintptr_t)1 && (I.Code==XCRON_SERVICE_MEMORY || I.Code==XCRON_SERVICE_SYSTEM),"selected cold OOM preserves output and typed failure");xrtClearError();}
        testRequire(xrtAllocationBudgetInfo(Budget,&BI) && !BI.LiveBytes && !BI.LiveCount,"every selected startup allocation prefix releases its ownership");xrtAllocationBudgetFree(Budget);
    }
    F=ssFixture(XRT_TIME_UNIX_EPOCH,&Local,1);C=ssConfig(E,&F);C.Service.BytesLimit=Arena+C.Service.Scheduler.BytesLimit+C.Service.AdapterBytesLimit-1;xcronservice* Out=(xcronservice*)(uintptr_t)1;xcronserviceissue I;testRequire(!xcronServiceCreateSelected(&C,&Out,&I) && I.Code==XCRON_SERVICE_LIMIT && Out==(xcronservice*)(uintptr_t)1,"complete selected arena and component byte reservation enforced");xrtClearError();++C.Service.BytesLimit;C.Service.Proc=ssUTCProc;ssStart(&F,&C);
    xcronzone* Z=NULL;testRequire(xcronZoneCreatePosix(XRT_STR_LITERAL("UTC0"),XCRON_ZONE_TZIF3,&Z,NULL),"selected warmed UTC job");const unsigned Rounds=2048;xcronjobconfig J=ssJob(Z,&F,XRT_TIME_UNIX_EPOCH,XRT_TIME_UNIX_EPOCH+(xtime)Rounds*1000);testRequire(xcronExpressionCompile(XRT_STR_LITERAL("* * * * * *"),XCRON_SECONDS6,&J.Expression,NULL),"selected warmed every-second expression");xcronjobid Job=ssAdd(&F,&J,(xcrondeliverypolicy){0,1});xcronZoneRelease(Z);xcronselectedservicecompletion D=ssDone(F.Service);testRequire(!D.Completion.Error,"warm first selected callback/receipt");ssInfo(F.Service,Job);xrtSetErrorInfo(XERR_STATE,"selected.caller",41,"preserve caller identity");const xerror* Ambient=xrtGetError();
#if defined(XRT_FEATURE_MEMORY_STATS)
    xmemstats Before,After;xrtMemStatsEnable(true);xrtMemStatsGet(&Before);
#endif
    for(unsigned N=1;N<=Rounds;++N){xtime When=XRT_TIME_UNIX_EPOCH+(xtime)N*1000;xrtAtomic64Store(&F.Wall,(uint64)When,XMEMORY_RELEASE);xrtAtomic64Store(&F.Mono,100+(uint64)N*1000,XMEMORY_RELEASE);testRequire(xcronServiceWake(F.Service,NULL),"wake warmed selected owner");D=ssDone(F.Service);testRequire(D.Completion.ScheduledAt==When && D.Completion.Result==XCRON_RUN_SUCCEEDED && !D.Completion.Error && D.Candidates==1,"warmed selected union/slot generation reuse");xcronselectedjobinfo Info=ssInfo(F.Service,Job);testRequire(Info.Policy.Missing==XCRON_MISSING_REJECT && xrtGetError()==Ambient,"selected ticket reuse/query and all successes preserve caller error identity");}
#if defined(XRT_FEATURE_MEMORY_STATS)
    xrtMemStatsGet(&After);xrtMemStatsEnable(false);testRequire(Before.MallocCalls==After.MallocCalls && Before.CallocCalls==After.CallocCalls && Before.ReallocCalls==After.ReallocCalls && Before.BlockAllocCalls==After.BlockAllocCalls,"warmed selected commands/owner/worker/metadata request no heap");
#endif
    xrtClearError();ssStop(&F);ssClear(&F);ssPoolEnd(E);
}
